#!/usr/bin/env python3
from __future__ import annotations

import json
import sys
from pathlib import Path

root = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path.cwd()
path = root / "src/main/java/net/migueel26/faunaandorchestra/block/entity/CrawlingDiscordBlockEntity.java"
text = path.read_text(encoding="utf-8")

text = text.replace("\nimport java.util.Iterator;\n", "\n", 1)

fields_old = '''    private int actionTimer = -1;\n\n    public CrawlingDiscordBlockEntity(BlockPos pos, BlockState state) {\n'''
fields_new = '''    private int actionTimer = -1;\n\n    // Hot spread scans are synchronous on the server thread. Reuse mutable\n    // coordinates so candidate/support/neighbor probes do not allocate a new\n    // BlockPos for every checked location. No position escapes these helpers.\n    private final BlockPos.MutableBlockPos spreadPos = new BlockPos.MutableBlockPos();\n    private final BlockPos.MutableBlockPos spreadDownPos = new BlockPos.MutableBlockPos();\n    private final BlockPos.MutableBlockPos blockProbe = new BlockPos.MutableBlockPos();\n    private final BlockPos.MutableBlockPos grabProbe = new BlockPos.MutableBlockPos();\n\n    public CrawlingDiscordBlockEntity(BlockPos pos, BlockState state) {\n'''
if text.count(fields_old) != 1:
    raise SystemExit("Wave 4 CrawlingDiscord field anchor changed unexpectedly")
text = text.replace(fields_old, fields_new, 1)

old_method = '''    private void performSpreadLogic(Level level, BlockPos pos, BlockState state) {\n        boolean climber = state.getValue(CrawlingDiscordBlock.CLIMBER);\n\n        if (!this.father && this.generation < this.maxGeneration) {\n            if (!climber) {\n                boolean transformToClimber = false;\n                Iterator<BlockPos> iteratorUp = BlockPos.betweenClosed(pos.north().west(), pos.south().east()).iterator();\n                Iterator<BlockPos> iteratorDown = BlockPos.betweenClosed(pos.below().north().west(), pos.below().south().east()).iterator();\n                int time = 0;\n\n                while (iteratorUp.hasNext()) {\n                    BlockPos nextPos = iteratorUp.next();\n                    BlockPos downPos = iteratorDown.next();\n                    if (time % 2 != 0) {\n                        if (level.getBlockState(nextPos).is(ModTags.Blocks.REPLACEABLE_BY_DISCORD) &&\n                                !level.getBlockState(nextPos.below()).isAir() &&\n                                !level.getBlockState(nextPos.below()).is(ModBlocks.CRAWLING_DISCORD.get())) {\n\n                            spawnChild(level, nextPos, state.setValue(CrawlingDiscordBlock.CLIMBER, false));\n                        }\n\n                        if (level.getBlockState(downPos).is(ModTags.Blocks.REPLACEABLE_BY_DISCORD) &&\n                                canGrab(downPos, level) &&\n                                level.getBlockState(downPos.above()).isAir()) {\n\n                            spawnChild(level, downPos, state.setValue(CrawlingDiscordBlock.CLIMBER, true));\n                        }\n                    }\n                    time++;\n                }\n\n                if (canGrab(pos, level)) transformToClimber = true;\n\n                if (!transformToClimber) {\n                    this.father = true;\n                    this.actionTimer = (this.maxGeneration == CrawlingDiscordBlock.DEFAULT_MAX_GENERATION) ? CrawlingDiscordBlock.DIE_TIME : 100;\n                    this.setChanged();\n                } else {\n                    level.setBlock(pos, state.setValue(CrawlingDiscordBlock.CLIMBER, true), 3);\n                    this.father = false;\n                    this.actionTimer = getNewChildTime(level);\n                    this.setChanged();\n                }\n\n            } else {\n                Iterator<BlockPos> iterator = BlockPos.betweenClosed(\n                        new BlockPos(pos.getX()+1,pos.getY()+1,pos.getZ()+1),\n                        new BlockPos(pos.getX()-1, pos.getY()-1, pos.getZ()-1)).iterator();\n\n                int time = 0;\n                while (iterator.hasNext()) {\n                    BlockPos nextPos = iterator.next();\n                    if (time % 2 == 0) {\n                        if (level.getBlockState(nextPos).is(ModTags.Blocks.REPLACEABLE_BY_DISCORD) && canGrab(nextPos, level)) {\n                            spawnChild(level, nextPos, state.setValue(CrawlingDiscordBlock.CLIMBER, true));\n                        }\n                    }\n                    time++;\n                }\n\n                this.father = true;\n                this.actionTimer = (this.maxGeneration == CrawlingDiscordBlock.DEFAULT_MAX_GENERATION) ? CrawlingDiscordBlock.DIE_TIME : 100;\n                this.setChanged();\n\n                if (level.getBlockState(pos.above()).is(ModTags.Blocks.REPLACEABLE_BY_DISCORD)) {\n                    spawnChild(level, pos.above(), state.setValue(CrawlingDiscordBlock.CLIMBER, false));\n                }\n            }\n\n        } else {\n            level.setBlock(pos, Blocks.AIR.defaultBlockState(), 3);\n        }\n    }\n'''

new_method = '''    private void performSpreadLogic(Level level, BlockPos pos, BlockState state) {\n        boolean climber = state.getValue(CrawlingDiscordBlock.CLIMBER);\n\n        if (!this.father && this.generation < this.maxGeneration) {\n            if (!climber) {\n                boolean transformToClimber = false;\n                int centerX = pos.getX();\n                int centerY = pos.getY();\n                int centerZ = pos.getZ();\n                int time = 0;\n\n                // Exact BlockPos.betweenClosed order for the original 3x1x3\n                // scan: X is the fastest axis, then Y, then Z. Native QA\n                // compares this order against vanilla before profiling.\n                for (int z = centerZ - 1; z <= centerZ + 1; z++) {\n                    for (int x = centerX - 1; x <= centerX + 1; x++) {\n                        this.spreadPos.set(x, centerY, z);\n                        this.spreadDownPos.set(x, centerY - 1, z);\n\n                        if ((time & 1) != 0) {\n                            if (isGroundChildPosition(level, this.spreadPos)) {\n                                spawnChild(level, this.spreadPos, state.setValue(CrawlingDiscordBlock.CLIMBER, false));\n                            }\n\n                            if (isClimberChildPosition(level, this.spreadDownPos)) {\n                                spawnChild(level, this.spreadDownPos, state.setValue(CrawlingDiscordBlock.CLIMBER, true));\n                            }\n                        }\n                        time++;\n                    }\n                }\n\n                if (canGrab(pos, level)) transformToClimber = true;\n\n                if (!transformToClimber) {\n                    this.father = true;\n                    this.actionTimer = (this.maxGeneration == CrawlingDiscordBlock.DEFAULT_MAX_GENERATION) ? CrawlingDiscordBlock.DIE_TIME : 100;\n                    this.setChanged();\n                } else {\n                    level.setBlock(pos, state.setValue(CrawlingDiscordBlock.CLIMBER, true), 3);\n                    this.father = false;\n                    this.actionTimer = getNewChildTime(level);\n                    this.setChanged();\n                }\n\n            } else {\n                int centerX = pos.getX();\n                int centerY = pos.getY();\n                int centerZ = pos.getZ();\n                int time = 0;\n\n                // Exact normalized BlockPos.betweenClosed 3x3x3 order.\n                for (int z = centerZ - 1; z <= centerZ + 1; z++) {\n                    for (int y = centerY - 1; y <= centerY + 1; y++) {\n                        for (int x = centerX - 1; x <= centerX + 1; x++) {\n                            this.spreadPos.set(x, y, z);\n                            if ((time & 1) == 0\n                                    && level.getBlockState(this.spreadPos).is(ModTags.Blocks.REPLACEABLE_BY_DISCORD)\n                                    && canGrab(this.spreadPos, level)) {\n                                spawnChild(level, this.spreadPos, state.setValue(CrawlingDiscordBlock.CLIMBER, true));\n                            }\n                            time++;\n                        }\n                    }\n                }\n\n                this.father = true;\n                this.actionTimer = (this.maxGeneration == CrawlingDiscordBlock.DEFAULT_MAX_GENERATION) ? CrawlingDiscordBlock.DIE_TIME : 100;\n                this.setChanged();\n\n                this.blockProbe.set(centerX, centerY + 1, centerZ);\n                if (level.getBlockState(this.blockProbe).is(ModTags.Blocks.REPLACEABLE_BY_DISCORD)) {\n                    spawnChild(level, this.blockProbe, state.setValue(CrawlingDiscordBlock.CLIMBER, false));\n                }\n            }\n\n        } else {\n            level.setBlock(pos, Blocks.AIR.defaultBlockState(), 3);\n        }\n    }\n\n    private boolean isGroundChildPosition(Level level, BlockPos childPos) {\n        if (!level.getBlockState(childPos).is(ModTags.Blocks.REPLACEABLE_BY_DISCORD)) {\n            return false;\n        }\n\n        this.blockProbe.set(childPos.getX(), childPos.getY() - 1, childPos.getZ());\n        BlockState support = level.getBlockState(this.blockProbe);\n        return !support.isAir() && !support.is(ModBlocks.CRAWLING_DISCORD.get());\n    }\n\n    private boolean isClimberChildPosition(Level level, BlockPos childPos) {\n        if (!level.getBlockState(childPos).is(ModTags.Blocks.REPLACEABLE_BY_DISCORD) || !canGrab(childPos, level)) {\n            return false;\n        }\n\n        this.blockProbe.set(childPos.getX(), childPos.getY() + 1, childPos.getZ());\n        return level.getBlockState(this.blockProbe).isAir();\n    }\n'''

if text.count(old_method) != 1:
    raise SystemExit("Wave 4 CrawlingDiscord spread method shape changed unexpectedly")
text = text.replace(old_method, new_method, 1)

can_grab_old = '''    private boolean canGrab(BlockPos newPos, Level level) {\n        return !level.getBlockState(newPos.east()).isAir() && !level.getBlockState(newPos.east()).is(ModBlocks.CRAWLING_DISCORD.get()) ||\n                !level.getBlockState(newPos.west()).isAir() && !level.getBlockState(newPos.west()).is(ModBlocks.CRAWLING_DISCORD.get()) ||\n                !level.getBlockState(newPos.north()).isAir() && !level.getBlockState(newPos.north()).is(ModBlocks.CRAWLING_DISCORD.get()) ||\n                !level.getBlockState(newPos.south()).isAir() && !level.getBlockState(newPos.south()).is(ModBlocks.CRAWLING_DISCORD.get());\n    }\n'''
can_grab_new = '''    private boolean canGrab(BlockPos newPos, Level level) {\n        int x = newPos.getX();\n        int y = newPos.getY();\n        int z = newPos.getZ();\n\n        // Preserve the original EAST -> WEST -> NORTH -> SOUTH short-circuit\n        // order while avoiding two relative BlockPos allocations/state reads\n        // per tested direction.\n        this.grabProbe.set(x + 1, y, z);\n        BlockState neighbor = level.getBlockState(this.grabProbe);\n        if (!neighbor.isAir() && !neighbor.is(ModBlocks.CRAWLING_DISCORD.get())) return true;\n\n        this.grabProbe.set(x - 1, y, z);\n        neighbor = level.getBlockState(this.grabProbe);\n        if (!neighbor.isAir() && !neighbor.is(ModBlocks.CRAWLING_DISCORD.get())) return true;\n\n        this.grabProbe.set(x, y, z - 1);\n        neighbor = level.getBlockState(this.grabProbe);\n        if (!neighbor.isAir() && !neighbor.is(ModBlocks.CRAWLING_DISCORD.get())) return true;\n\n        this.grabProbe.set(x, y, z + 1);\n        neighbor = level.getBlockState(this.grabProbe);\n        return !neighbor.isAir() && !neighbor.is(ModBlocks.CRAWLING_DISCORD.get());\n    }\n'''
if text.count(can_grab_old) != 1:
    raise SystemExit("Wave 4 CrawlingDiscord canGrab shape changed unexpectedly")
text = text.replace(can_grab_old, can_grab_new, 1)

checks = {
    "no_betweenClosed_hot_loop": "BlockPos.betweenClosed(" not in text,
    "no_relative_neighbor_probes": all(s not in text for s in ["newPos.east()", "newPos.west()", "newPos.north()", "newPos.south()"]),
    "reusable_mutable_positions": all(s in text for s in ["spreadPos", "spreadDownPos", "blockProbe", "grabProbe"]),
    "non_climber_3x3_bounds": "for (int z = centerZ - 1; z <= centerZ + 1; z++)" in text and "for (int x = centerX - 1; x <= centerX + 1; x++)" in text,
    "climber_3x3x3_y_axis": "for (int y = centerY - 1; y <= centerY + 1; y++)" in text,
    "parity_preserved": "if ((time & 1) != 0)" in text and "if ((time & 1) == 0" in text,
    "neighbor_order_preserved": text.index("x + 1") < text.index("x - 1") < text.index("z - 1") < text.index("z + 1"),
    "timers_untouched": "CrawlingDiscordBlock.DIE_TIME" in text and "getNewChildTime(level)" in text,
}
if not all(checks.values()):
    raise SystemExit(f"Wave 4 invariant failed: {checks}")

path.write_text(text, encoding="utf-8", newline="\n")
report = {
    "target": "Fauna & Orchestra 3.0.3 native-profiled frontier Wave 4",
    "baseline_wave": "accepted Wave 3A + Wave 3C",
    "changed_files": [str(path.relative_to(root))],
    "optimization": [
        "Replace Crawling Discord betweenClosed iterator/bound-position allocation with direct X-fast/Y/Z loops using reusable MutableBlockPos candidates.",
        "Reuse support/above probes and cache each support BlockState once instead of repeated below()/above() position creation and state reads.",
        "Preserve EAST/WEST/NORTH/SOUTH canGrab short-circuit order while reusing one MutableBlockPos and one BlockState read per direction."
    ],
    "preserved": [
        "same 3x1x3 and normalized 3x3x3 traversal order",
        "same odd/even time parity selection",
        "same replaceable/support/canGrab predicates",
        "same generation limits and child timers",
        "same child count and placement candidates",
        "same CLIMBER states, death timing, particles and content"
    ],
    "invariants": checks
}
(root / "FRONTIER-WAVE4-REPORT.json").write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
print(json.dumps(report, indent=2))
